@SpringBootTest(properties={"spring.datasource.url=jdbc:h2:mem:catalog-identity;DB_CLOSE_DELAY=-1;MODE=MYSQL","mybatis-plus.configuration.log-impl=org.apache.ibatis.logging.nologging.NoLoggingImpl"})
@AutoConfigureMockMvc
@ActiveProfiles("test")
public class CatalogIdentityServiceTest {
    @Autowired protected CatalogIdentityService service;
    @Autowired protected JdbcTemplate jdbc;
    @Autowired protected PublisherService publishers;
    @Autowired protected BookCategoryService categories;
    @Autowired protected IntakeCatalog intake;
    @Autowired protected BookService books;
    @Autowired protected PlatformTransactionManager transactions;
    @Autowired protected MockMvc mvc;
    @Autowired protected com.fasterxml.jackson.databind.ObjectMapper applicationJson;
    protected final Actor admin=new Actor(811001,true,false),clerk=new Actor(811002,false,true),reader=new Actor(811003,false,false);
    protected UsernamePasswordAuthenticationToken auth(Actor a){return new UsernamePasswordAuthenticationToken(a.id(),"synthetic",List.of(new SimpleGrantedAuthority(a.admin()?"ROLE_ADMIN":a.librarian()?"ROLE_LIBRARIAN":"ROLE_READER")));}
    @BeforeEach protected void authenticate(){SecurityContextHolder.getContext().setAuthentication(auth(admin));}
    @AfterEach protected void clear(){SecurityContextHolder.clearContext();}
    protected long publisher(){return insert(jdbc,"INSERT INTO publisher(name,address) VALUES (?,?)","合成出版社"+UUID.randomUUID(),"DO_NOT_EXPOSE_SYNTHETIC_CONTACT");}
    protected long category(){return insert(jdbc,"INSERT INTO book_category(name) VALUES (?)","合成主题"+UUID.randomUUID());}
    protected long child(long parent){return insert(jdbc,"INSERT INTO book_category(name,parent_id,level) VALUES (?,?,2)","合成子类"+UUID.randomUUID(),parent);}
    protected long book(){long c=category();return insert(jdbc,"INSERT INTO book(isbn,title,publisher,category_id,stock_total,stock_available) VALUES (?,?,?,?,0,0)",UUID.randomUUID().toString().replace("-","").substring(0,20),"合成书目"+UUID.randomUUID(),"原登记出版社",c);}
    protected ObjectNode changes(){return obj("publisher",null,"themes",null,"aliases",List.of(),"categoryDimensions",List.of());}
    protected ObjectNode input(long b,ObjectNode changes){JsonNode v=service.book(b,admin);return obj("operationKey",UUID.randomUUID().toString(),"mode","MANUAL","reason","合成核实依据","bookId",b,"expectedRevision",v.get("identityRevision"),"expectedCatalogDigest",v.get("catalogDigest"),"sourceDigest",null,"changes",changes);}
    protected ObjectNode link(long publisher){return changes().set("publisher",obj("action","LINK","publisherId",publisher));}
    protected JsonNode preview(long b,ObjectNode changes){return service.preview(input(b,changes),admin);}
    protected JsonNode confirm(JsonNode p){return service.confirm(p.path("requestId").asLong(),obj("operationKey",p.get("operationKey"),"previewDigest",p.get("previewDigest")),admin);}
    protected void reason(String code,Runnable call){Failure e=assertThrows(Failure.class,call::run);assertEquals(code,e.code);}
    protected ObjectNode topic(long...ids){List<JsonNode> d=new ArrayList<>();for(long id:ids)d.add(obj("categoryId",id,"dimension","TOPIC"));return changes().set("categoryDimensions",tree(d));}
    protected void rename(long p,String name){PublisherRequest r=new PublisherRequest();r.setId(p);r.setName(name);r.setStatus(1);publishers.update(r);}
    protected JsonNode http(org.springframework.test.web.servlet.request.MockHttpServletRequestBuilder r,JsonNode body,Actor a,int status)throws Exception{if(body!=null)r.contentType("application/json").content(write(body));r.with(a==null?anonymous():authentication(auth(a)));var response=mvc.perform(r).andReturn().getResponse();assertEquals(status,response.getStatus(),response.getContentAsString());authenticate();return JSON.readTree(response.getContentAsString()).path("data");}

    @Test void readsAreSafeBoundedDefaultsAndClerkDoesNotReceiveCandidates(){long b=book();int count=jdbc.queryForObject("SELECT COUNT(*) FROM catalog_identity_request",Integer.class);JsonNode v=service.book(b,clerk);assertTrue(v.get("publisherId").isNull());assertEquals("LEGACY",v.path("categoryFieldKind").asText());assertFalse(v.has("candidates"));assertTrue(service.book(b,admin).has("candidates"));assertEquals(count,jdbc.queryForObject("SELECT COUNT(*) FROM catalog_identity_request",Integer.class));assertFalse(write(service.publishers(null,1,100,admin)).contains("DO_NOT_EXPOSE_SYNTHETIC_CONTACT"));reason("INVALID_INPUT",()->service.publishers(null,1,101,admin));}
    @Test void legacyCategorySortOrderAbaInvalidatesFrozenTargetAndAuditsBothChanges()throws Exception{long b=book(),c=category();int original=jdbc.queryForObject("SELECT sort_order FROM book_category WHERE id=?",Integer.class,c);String name=jdbc.queryForObject("SELECT name FROM book_category WHERE id=?",String.class,c);ObjectNode changes=topic(c);changes.set("themes",obj("action","REPLACE","categoryIds",List.of(c)));JsonNode preview=preview(b,changes);http(put("/categories"),obj("id",c,"name",name,"sortOrder",original+11),admin,200);http(put("/categories"),obj("id",c,"name",name,"sortOrder",original),admin,200);assertEquals(original,jdbc.queryForObject("SELECT sort_order FROM book_category WHERE id=?",Integer.class,c));assertEquals(2,jdbc.queryForObject("SELECT catalog_identity_revision FROM book_category WHERE id=?",Integer.class,c));var events=jdbc.query("SELECT before_json,after_json FROM catalog_identity_event WHERE entity_kind='CATEGORY' AND entity_id=? ORDER BY id",(rs,row)->obj("before",read(rs.getString("before_json")),"after",read(rs.getString("after_json"))),c);assertEquals(2,events.size());JsonNode firstBefore=events.get(0).get("before"),firstAfter=events.get(0).get("after"),secondBefore=events.get(1).get("before"),secondAfter=events.get(1).get("after");assertEquals(original,firstBefore.path("sortOrder").asInt());assertEquals(original+11,firstAfter.path("sortOrder").asInt());assertEquals(original+11,secondBefore.path("sortOrder").asInt());assertEquals(original,secondAfter.path("sortOrder").asInt());reason("CATALOG_IDENTITY_CHANGED",()->confirm(preview));assertEquals("PREVIEWED",service.getByKey(preview.path("operationKey").asText(),admin).path("state").asText());assertEquals(0,jdbc.queryForObject("SELECT COUNT(*) FROM catalog_book_theme WHERE book_id=?",Integer.class,b));}
    @Test void strictInputAndHttpRolesAreCheckedBeforeObjectExistence()throws Exception{http(get("/catalog-identities/books/99999999"),null,reader,403);http(get("/catalog-identities/books/99999999"),null,null,401);http(post("/catalog-identities/previews"),obj(),clerk,403);long b=book();ObjectNode valid=input(b,link(publisher()));List<JsonNode> bad=new ArrayList<>();bad.add(NullNode.instance);bad.add(tree(List.of()));bad.add(valid.deepCopy().put("unknown",1));bad.add(valid.deepCopy().put("bookId","2"));bad.add(valid.deepCopy().putNull("changes"));bad.add(valid.deepCopy().set("changes",obj("stranger",1)));ObjectNode missing=valid.deepCopy();missing.remove("expectedRevision");bad.add(missing);bad.add(valid.deepCopy().set("changes",changes().set("themes",obj("action","REPLACE","categoryIds",List.of(1,1)))));for(JsonNode n:bad)http(post("/catalog-identities/previews"),n,admin,400);http(post("/catalog-identities/previews"),valid.deepCopy().put("mode","SOURCE"),admin,409);http(post("/catalog-identities/previews").contentType("application/json").content("{"),null,admin,400);ObjectNode minimal=valid.deepCopy();((ObjectNode)minimal.get("changes")).remove(List.of("themes","aliases","categoryDimensions"));assertEquals("PREVIEWED",service.preview(minimal,admin).path("state").asText());}
    @Test void previewAndNoOpNeverAdoptAndManualLinkPreservesLegacy(){long p=publisher(),b=book();String raw=jdbc.queryForObject("SELECT publisher FROM book WHERE id=?",String.class,b);long category=jdbc.queryForObject("SELECT category_id FROM book WHERE id=?",Long.class,b);JsonNode preview=preview(b,link(p));assertEquals(0,jdbc.queryForObject("SELECT COUNT(*) FROM catalog_book_publisher WHERE book_id=?",Integer.class,b));assertEquals(p,preview.path("preview").path("book").path("after").path("publisherId").asLong());JsonNode receipt=confirm(preview);assertEquals(p,receipt.path("book").path("identity").path("publisherId").asLong());assertEquals(raw,jdbc.queryForObject("SELECT publisher FROM book WHERE id=?",String.class,b));assertEquals(category,jdbc.queryForObject("SELECT category_id FROM book WHERE id=?",Long.class,b));JsonNode noop=confirm(preview(b,link(p)));assertFalse(noop.path("book").path("changed").asBoolean());assertTrue(noop.path("book").get("eventId").isNull());assertEquals(receipt,confirm(preview));}
    @Test void multiThemesRequireExplicitTopicAndAllEnabledParents(){long b=book(),root=category(),child=child(root),second=category();ObjectNode themes=changes().set("themes",obj("action","REPLACE","categoryIds",List.of(child,second)));reason("CATEGORY_TOPIC_REQUIRED",()->preview(b,themes));ObjectNode choices=topic(root,child,second);choices.set("themes",obj("action","REPLACE","categoryIds",List.of(second,child)));JsonNode p=preview(b,choices);assertEquals(0,jdbc.queryForObject("SELECT COUNT(*) FROM catalog_category_profile WHERE category_id IN (?,?,?)",Integer.class,root,child,second));JsonNode r=confirm(p);assertEquals(2,r.path("book").path("identity").path("themes").size());JsonNode c=service.categories(null,1,100,clerk);assertTrue(write(c).contains("parentChainActive"));jdbc.update("UPDATE book_category SET status=0,catalog_identity_revision=catalog_identity_revision+1 WHERE id=?",root);reason("CATEGORY_PARENT_DISABLED",()->preview(b,themes));assertEquals(0,jdbc.queryForObject("SELECT COUNT(*) FROM catalog_book_age_label WHERE book_id=?",Integer.class,b));}
    @Test void clearPublisherAndEmptyThemesAndRepeatedRequestWork(){long b=book(),p=publisher(),c=category();ObjectNode choices=topic(c);choices.set("publisher",obj("action","LINK","publisherId",p));choices.set("themes",obj("action","REPLACE","categoryIds",List.of(c)));confirm(preview(b,choices));ObjectNode clear=changes();clear.set("publisher",obj("action","CLEAR","publisherId",null));clear.set("themes",obj("action","REPLACE","categoryIds",List.of()));JsonNode request=preview(b,clear),receipt=confirm(request);assertTrue(receipt.path("book").path("identity").get("publisher").isNull());assertEquals(0,receipt.path("book").path("identity").path("themes").size());assertEquals(receipt,confirm(request));assertEquals(receipt,service.getByKey(request.path("operationKey").asText(),admin).path("receipt"));reason("CATALOG_IDENTITY_HISTORY_REFERENCED",()->publishers.delete(p));}
    @Test void exactAliasBytesCanCoexistAndRetirementIsExplicitAuditedAndNoOpSafe(){long p=publisher(),b=book();List<JsonNode> values=new ArrayList<>();for(String name:List.of("Aa","aa","é","e","Aa "))values.add(obj("kind","PUBLISHER","ownerId",p,"action","ADD","name",name));ObjectNode c=changes();c.set("aliases",tree(values));JsonNode request=preview(b,c);assertEquals(5,request.path("preview").path("book").path("aliasChanges").size());assertEquals(0,jdbc.queryForObject("SELECT COUNT(*) FROM catalog_publisher_alias WHERE publisher_id=?",Integer.class,p));confirm(request);assertEquals(5,jdbc.queryForObject("SELECT COUNT(*) FROM catalog_publisher_alias WHERE publisher_id=?",Integer.class,p));JsonNode no=confirm(preview(b,c));assertFalse(no.path("book").path("changed").asBoolean());ObjectNode retire=changes();retire.set("aliases",tree(List.of(obj("kind","PUBLISHER","ownerId",p,"action","CLEAR","name","Aa"))));JsonNode r=confirm(preview(b,retire));assertEquals("RETIRED",r.path("book").path("aliasChanges").get(0).path("afterAliases").get(0).path("status").asText());assertEquals(4,jdbc.queryForObject("SELECT COUNT(*) FROM catalog_publisher_alias WHERE publisher_id=? AND status='ACTIVE'",Integer.class,p));}
    @Test void ownerAndParentAbaRejectOldPreviewAndOldCrudCreatesSafeAudit(){long p=publisher(),b=book();String original=jdbc.queryForObject("SELECT name FROM publisher WHERE id=?",String.class,p);JsonNode request=preview(b,link(p));rename(p,"合成ABA"+UUID.randomUUID());rename(p,original);reason("CATALOG_IDENTITY_CHANGED",()->confirm(request));assertEquals(2,jdbc.queryForObject("SELECT catalog_identity_revision FROM publisher WHERE id=?",Integer.class,p));assertEquals(2,jdbc.queryForObject("SELECT COUNT(*) FROM catalog_identity_event WHERE entity_kind='PUBLISHER' AND entity_id=?",Integer.class,p));long parent=category(),child=child(parent);ObjectNode choices=topic(parent,child);choices.set("themes",obj("action","REPLACE","categoryIds",List.of(child)));JsonNode req=preview(b,choices);String parentOriginal=jdbc.queryForObject("SELECT name FROM book_category WHERE id=?",String.class,parent);CategoryRequest x=new CategoryRequest();x.setId(parent);x.setName("ABA parent");categories.update(x);x.setName(parentOriginal);categories.update(x);reason("CATALOG_IDENTITY_CHANGED",()->confirm(req));}
    @Test void legacyBookPublisherAbaAndNormalizeAreRevisionProtected(){long b=book(),p=publisher();JsonNode request=preview(b,link(p));InventoryIntakeContracts.MetadataUpdate n=new InventoryIntakeContracts.MetadataUpdate();n.setExpectedMetadataDigest(intake.view(b).metadataDigest());n.setChanges(obj("publisher","changed"));intake.update(b,n);n.setExpectedMetadataDigest(intake.view(b).metadataDigest());n.setChanges(obj("publisher","原登记出版社"));intake.update(b,n);reason("CATALOG_IDENTITY_CHANGED",()->confirm(request));assertEquals(2,service.book(b,clerk).path("identityRevision").asInt());}
    @Test void disabledTargetsAndLegacyAgeNeverBecomeNewLinks(){long p=publisher(),b=book(),c=category();jdbc.update("UPDATE publisher SET status=0 WHERE id=?",p);reason("PUBLISHER_DISABLED",()->preview(b,link(p)));ObjectNode d=changes();d.set("categoryDimensions",tree(List.of(obj("categoryId",c,"dimension","LEGACY_AGE"))));confirm(preview(b,d));ObjectNode t=changes();t.set("themes",obj("action","REPLACE","categoryIds",List.of(c)));reason("CATEGORY_TOPIC_REQUIRED",()->preview(b,t));}
    @Test void identityHistoryAndActivePreviewProtectLogicalDeletion(){long p=publisher(),b=book();JsonNode request=preview(b,link(p));reason("CATALOG_IDENTITY_HISTORY_REFERENCED",()->publishers.delete(p));reason("CATALOG_IDENTITY_HISTORY_REFERENCED",()->books.delete(b));jdbc.update("UPDATE catalog_identity_request SET expires_at='2000-01-01' WHERE id=?",request.path("requestId").asLong());reason("PREVIEW_EXPIRED",()->confirm(request));}
    protected boolean mysql(){try(var c=jdbc.getDataSource().getConnection()){return c.getMetaData().getDatabaseProductName().equals("MySQL");}catch(Exception e){throw new RuntimeException(e);}}
    protected void dropCheck(String table,String constraint){jdbc.execute("ALTER TABLE "+table+" DROP "+(mysql()?"CHECK ":"CONSTRAINT ")+constraint);}
    @Test void auditFailureRollsBackAliasesDimensionsLinksRevisionAndReceipt(){long p=publisher(),b=book(),c=category();ObjectNode change=topic(c);change.set("publisher",obj("action","LINK","publisherId",p));change.set("themes",obj("action","REPLACE","categoryIds",List.of(c)));change.set("aliases",tree(List.of(obj("kind","PUBLISHER","ownerId",p,"action","ADD","name","Rollback alias"))));JsonNode preview=preview(b,change);String constraint="ck_synthetic_b35_audit";jdbc.execute("ALTER TABLE catalog_identity_event ADD CONSTRAINT "+constraint+" CHECK(book_id<>"+b+")");try{reason("CATALOG_IDENTITY_SAVE_FAILED",()->confirm(preview));assertEquals(0,jdbc.queryForObject("SELECT COUNT(*) FROM catalog_book_publisher WHERE book_id=?",Integer.class,b));assertEquals(0,jdbc.queryForObject("SELECT COUNT(*) FROM catalog_publisher_alias WHERE publisher_id=?",Integer.class,p));assertEquals(0,jdbc.queryForObject("SELECT COUNT(*) FROM catalog_category_profile WHERE category_id=?",Integer.class,c));assertEquals(0,service.book(b,clerk).path("identityRevision").asInt());assertEquals("PREVIEWED",service.getRequest(preview.path("requestId").asLong(),admin).path("state").asText());}finally{dropCheck("catalog_identity_event",constraint);}confirm(preview);}
    @Test void concurrentSameKeyAndConfirmationAreIdempotent()throws Exception{long b=book(),p=publisher();ObjectNode n=input(b,link(p));ExecutorService pool=Executors.newFixedThreadPool(2);try{Future<JsonNode>x=pool.submit(()->service.preview(n,admin)),y=pool.submit(()->service.preview(n,admin));JsonNode request=x.get(15,TimeUnit.SECONDS);assertEquals(request,y.get(15,TimeUnit.SECONDS));Future<JsonNode>first=pool.submit(()->confirm(request)),second=pool.submit(()->confirm(request));assertEquals(first.get(15,TimeUnit.SECONDS),second.get(15,TimeUnit.SECONDS));assertEquals(1,jdbc.queryForObject("SELECT COUNT(*) FROM catalog_identity_event WHERE book_id=? AND entity_kind='BOOK_PUBLISHER'",Integer.class,b));}finally{pool.shutdownNow();assertTrue(pool.awaitTermination(5,TimeUnit.SECONDS));}}
    @Test void candidateIdentityIsStableIdAndApproximateIsOnlyEvidence(){long p=publisher(),b=book();String name=jdbc.queryForObject("SELECT name FROM publisher WHERE id=?",String.class,p);jdbc.update("UPDATE book SET publisher=? WHERE id=?",name,b);JsonNode v=service.book(b,admin);JsonNode match=v.path("candidates").get(0);assertTrue(match.get("id").isNull());assertEquals(p,match.path("entityId").asLong());assertEquals("EXACT",match.path("matchKind").asText());JsonNode no=confirm(preview(b,changes()));assertFalse(no.path("book").path("changed").asBoolean());assertTrue(service.book(b,clerk).get("publisherId").isNull());}
    @Test void exportSyntheticContractsForFrontend()throws Exception{long p=publisher(),b=book(),root=category(),child=child(root);ObjectNode evidence=obj("publisherList",service.publishers(null,1,100,admin),"categoryList",service.categories(null,1,100,admin),"book",service.book(b,admin));JsonNode pp=preview(b,link(p));evidence.set("publisherPreview",pp);evidence.set("publisherReceipt",confirm(pp));ObjectNode themes=topic(root,child);themes.set("themes",obj("action","REPLACE","categoryIds",List.of(child)));JsonNode tp=preview(b,themes);evidence.set("themePreview",tp);evidence.set("themeReceipt",confirm(tp));ObjectNode alias=changes();alias.set("aliases",tree(List.of(obj("kind","PUBLISHER","ownerId",p,"action","ADD","name","合成别名"))));JsonNode ap=preview(b,alias);evidence.set("aliasPreview",ap);evidence.set("aliasReceipt",confirm(ap));String dir=System.getProperty("b35.evidence.dir");if(dir!=null){Path path=Path.of(dir);Files.createDirectories(path);Files.writeString(path.resolve("synthetic-contracts.json"),JSON.writerWithDefaultPrettyPrinter().writeValueAsString(evidence));}}
    @Test void technicalRevisionIsHiddenAndV8MetadataDigestRemainsIndependent()throws Exception{long b=book(),p=publisher();String digest=intake.view(b).metadataDigest();JsonNode prior=http(get("/books/"+b),null,null,200);assertFalse(prior.has("catalogIdentityRevision"));confirm(preview(b,link(p)));assertEquals(digest,intake.view(b).metadataDigest());JsonNode entity=applicationJson.valueToTree(intake.view(b).book());assertFalse(entity.has("catalogIdentityRevision"));assertFalse(applicationJson.valueToTree(publishers.getById(p)).has("catalogIdentityRevision"));long c=jdbc.queryForObject("SELECT category_id FROM book WHERE id=?",Long.class,b);assertFalse(applicationJson.valueToTree(categories.getById(c)).has("catalogIdentityRevision"));}
    @Test void topicParentCannotBeReclassifiedWhileDescendantIsLinked(){long b=book(),root=category(),child=child(root);ObjectNode setup=topic(root,child);setup.set("themes",obj("action","REPLACE","categoryIds",List.of(child)));confirm(preview(b,setup));ObjectNode downgrade=changes();downgrade.set("categoryDimensions",tree(List.of(obj("categoryId",root,"dimension","LEGACY_AGE"))));reason("CATEGORY_DIMENSION_REFERENCED",()->preview(b,downgrade));}
    @Test void legacyNormalizeSingleAndBatchBothRejectEarlierIdentityPreview()throws Exception{long b=book(),p=publisher();JsonNode request=preview(b,link(p));String raw=jdbc.queryForObject("SELECT publisher FROM book WHERE id=?",String.class,b);http(put("/book-normalize/"+b),obj("publisher","合成其他出版社"),admin,200);http(put("/book-normalize/batch"),tree(List.of(obj("id",b,"publisher",raw))),admin,200);assertEquals(2,service.book(b,clerk).path("identityRevision").asInt());reason("CATALOG_IDENTITY_CHANGED",()->confirm(request));}
    @Test void identityConfirmationPreservesEveryOldBusinessColumnIncludingHistoricalUpdateTime(){long b=book(),p=publisher(),c=category();for(var e:Map.of("book",b,"publisher",p,"book_category",c).entrySet())jdbc.update("UPDATE "+e.getKey()+" SET update_time='2001-02-03 04:05:06' WHERE id=?",e.getValue());Map<String,Map<String,Object>> old=new TreeMap<>();for(var e:Map.of("book",b,"publisher",p,"book_category",c).entrySet()){Map<String,Object> row=jdbc.queryForMap("SELECT * FROM "+e.getKey()+" WHERE id=?",e.getValue());row.remove("catalog_identity_revision");old.put(e.getKey(),row);}ObjectNode changes=topic(c);changes.set("publisher",obj("action","LINK","publisherId",p));changes.set("themes",obj("action","REPLACE","categoryIds",List.of(c)));changes.set("aliases",tree(List.of(obj("kind","PUBLISHER","ownerId",p,"action","ADD","name","保值合成别名"))));confirm(preview(b,changes));for(var e:Map.of("book",b,"publisher",p,"book_category",c).entrySet()){Map<String,Object> row=jdbc.queryForMap("SELECT * FROM "+e.getKey()+" WHERE id=?",e.getValue());assertTrue(((Number)row.remove("catalog_identity_revision")).longValue()>0);assertEquals(old.get(e.getKey()),row,e.getKey());}}
    @Test void httpKeepsExactUtf8AndLiteralAliasTextAndRejectsDuplicateKeys()throws Exception{long b=book(),p=publisher();List<JsonNode> aliases=new ArrayList<>();for(int i=0;i<25;i++)aliases.add(obj("kind","PUBLISHER","ownerId",p,"action","ADD","name",("合成字📚".repeat(25))+i));aliases.add(obj("kind","PUBLISHER","ownerId",p,"action","ADD","name"," <script>原文</script> union select "));ObjectNode c=changes();c.set("aliases",tree(aliases));ObjectNode n=input(b,c);JsonNode preview=http(post("/catalog-identities/previews"),n,admin,200);JsonNode receipt=http(post("/catalog-identities/"+preview.path("requestId").asLong()+"/confirm"),obj("operationKey",preview.get("operationKey"),"previewDigest",preview.get("previewDigest")),admin,200);assertEquals(26,receipt.path("book").path("aliasChanges").size());assertEquals(aliases.get(0).path("name").asText(),jdbc.queryForObject("SELECT alias_name FROM catalog_publisher_alias WHERE publisher_id=? ORDER BY id LIMIT 1",String.class,p));assertEquals(1,jdbc.queryForObject("SELECT COUNT(*) FROM catalog_publisher_alias WHERE publisher_id=? AND alias_key=?",Integer.class,p,bytes(" <script>原文</script> union select ")));String duplicate=write(input(book(),link(p)));duplicate=duplicate.substring(0,duplicate.length()-1)+",\"bookId\":123}";http(post("/catalog-identities/previews").contentType("application/json").content(duplicate),null,admin,400);}
}
